// ignore_for_file: unused_element, unnecessary_cast


class GetAppsApp {
  /// App code.
  final String appCode;
  /// Creation time (Greenwich mean time).
  final String createdTime;
  /// App description.
  final String description;
  /// App ID, which is generated by the system and globally unique.
  final int id;
  /// Last modification time (Greenwich mean time).
  final String modifiedTime;
  /// App name.
  final String name;

  /// Creates a new [GetAppsApp].
  /// [appCode] App code.
  /// [createdTime] Creation time (Greenwich mean time).
  /// [description] App description.
  /// [id] App ID, which is generated by the system and globally unique.
  /// [modifiedTime] Last modification time (Greenwich mean time).
  /// [name] App name.
  GetAppsApp({
    required this.appCode,
    required this.createdTime,
    required this.description,
    required this.id,
    required this.modifiedTime,
    required this.name,
  });

  Map<String, dynamic> toMap() {
    return <String, dynamic>{
      'appCode': appCode,
      'createdTime': createdTime,
      'description': description,
      'id': id,
      'modifiedTime': modifiedTime,
      'name': name,
    };
  }

  factory GetAppsApp.fromMap(Map<String, dynamic> map) {
    return GetAppsApp(
      appCode: map['appCode'] as String,
      createdTime: map['createdTime'] as String,
      description: map['description'] as String,
      id: map['id'] as int,
      modifiedTime: map['modifiedTime'] as String,
      name: map['name'] as String,
    );
  }
}

